/*
 * ESP32 NTP Clock on LCD I2C
 * Connects to Wi-Fi, fetches UTC time via ntpEpoch(),
 * and displays HH:MM:SS on a 16x2 LCD.
 *
 * Wiring: LCD VCC -> 3V3, GND -> GND, SDA -> D21, SCL -> D22
 */

#include <WiFi.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

var ssid     = "ArduSimNet";
var password = "simulator";

LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  Serial.begin(115200);
  lcd.init();
  lcd.backlight();

  lcd.setCursor(0, 0);
  lcd.print("Connecting...");
  Serial.println("Connecting to Wi-Fi...");

  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP: ");
  Serial.println(WiFi.localIP());

  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("  NTP Clock");
  lcd.setCursor(0, 1);
  lcd.print(WiFi.localIP());
  delay(1500);
}

void loop() {
  var epoch = ntpEpoch();
  var hours   = Math.floor((epoch % 86400) / 3600);
  var minutes = Math.floor((epoch % 3600)   / 60);
  var seconds = epoch % 60;

  var hh = hours < 10 ? "0" + hours : "" + hours;
  var mm = minutes < 10 ? "0" + minutes : "" + minutes;
  var ss = seconds < 10 ? "0" + seconds : "" + seconds;

  lcd.setCursor(0, 0);
  lcd.print("  NTP Time (UTC)");

  lcd.setCursor(0, 1);
  lcd.print("    ");
  lcd.print(hh);
  lcd.print(":");
  lcd.print(mm);
  lcd.print(":");
  lcd.print(ss);
  lcd.print("    ");

  Serial.print("Time: ");
  Serial.print(hh);
  Serial.print(":");
  Serial.print(mm);
  Serial.print(":");
  Serial.println(ss);

  delay(1000);
 }
